SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- -------------------------------------------------------------------------
CREATE TABLE tenants (
  id VARCHAR(64) PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  legal_name TEXT,
  email TEXT NOT NULL,
  phone TEXT,
  address_line1 TEXT,
  address_line2 TEXT,
  city TEXT,
  state TEXT,
  state_code TEXT,
  pincode TEXT,
  country TEXT NOT NULL,
  gstin TEXT,
  pan TEXT,
  tan TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','trial','suspended','cancelled')),
  timezone TEXT NOT NULL,
  currency TEXT NOT NULL,
  franchise_id VARCHAR(255),
  is_demo INT NOT NULL DEFAULT 0,
  onboarding_step TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE franchises (
  id VARCHAR(64) PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT NOT NULL UNIQUE,
  owner_name TEXT,
  owner_email TEXT,
  owner_phone TEXT,
  city TEXT,
  state TEXT,
  status TEXT NOT NULL
                        CHECK (status IN ('onboarding','active','suspended','terminated')),
  revenue_share_pct DOUBLE NOT NULL DEFAULT 20.0,
  branding_json TEXT,
  onboarded_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE branches (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  code VARCHAR(255) NOT NULL,
  is_head_office INT NOT NULL DEFAULT 0,
  address_line1 TEXT,
  city TEXT,
  state TEXT,
  state_code TEXT,
  pincode TEXT,
  phone TEXT,
  email TEXT,
  manager_user_id TEXT,
  latitude DOUBLE,
  longitude DOUBLE,
  geofence_m INT NOT NULL DEFAULT 200,
  status TEXT NOT NULL CHECK (status IN ('active','inactive')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, code),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE companies (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  branch_id VARCHAR(64),
  name TEXT NOT NULL,
  legal_name TEXT,
  entity_type TEXT NOT NULL
                    CHECK (entity_type IN ('proprietorship','partnership','llp','private_limited','public_limited','trust','society','huf','other')),
  gstin VARCHAR(255),
  pan TEXT,
  tan TEXT,
  cin TEXT,
  registration_no TEXT,
  email TEXT,
  phone TEXT,
  website TEXT,
  address_line1 TEXT,
  address_line2 TEXT,
  city TEXT,
  state TEXT,
  state_code TEXT NOT NULL,
  pincode TEXT,
  country TEXT NOT NULL,
  financial_year_start TEXT NOT NULL,
  gst_registration_type TEXT NOT NULL
                    CHECK (gst_registration_type IN ('regular','composition','casual','non_resident','sez','unregistered')),
  gst_filing_frequency TEXT NOT NULL
                    CHECK (gst_filing_frequency IN ('monthly','quarterly')),
  logo_key TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active','trial','inactive','suspended','archived')),
  is_demo INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE users (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  email VARCHAR(255) NOT NULL,
  password_hash TEXT NOT NULL,
  full_name TEXT NOT NULL,
  phone TEXT,
  avatar_key TEXT,
  job_title TEXT,
  branch_id VARCHAR(64),
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                          CHECK (status IN ('active','invited','suspended','locked','deactivated')),
  email_verified_at TEXT,
  phone_verified_at TEXT,
  twofa_enabled INT NOT NULL DEFAULT 0,
  twofa_secret TEXT,
  twofa_backup_codes TEXT,
  twofa_enrolled_at TEXT,
  must_change_password INT NOT NULL DEFAULT 0,
  failed_login_count INT NOT NULL DEFAULT 0,
  locked_until TEXT,
  last_login_at TEXT,
  last_login_ip TEXT,
  locale TEXT NOT NULL,
  timezone TEXT NOT NULL,
  theme TEXT NOT NULL CHECK (theme IN ('dark','light','system')),
  is_demo INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  tenant_id_k VARCHAR(64) AS (IFNULL(tenant_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE roles (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  `key` VARCHAR(255) NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  level INT NOT NULL DEFAULT 50,
  is_system INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  tenant_id_k VARCHAR(64) AS (IFNULL(tenant_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE permissions (
  `key` VARCHAR(64) PRIMARY KEY,
  resource TEXT NOT NULL,
  action TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  category TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE role_permissions (
  role_id VARCHAR(64) NOT NULL,
  permission_key VARCHAR(64) NOT NULL,
  granted INT NOT NULL DEFAULT 1,
  PRIMARY KEY (role_id, permission_key),
  FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,
  FOREIGN KEY (permission_key) REFERENCES permissions(`key`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE user_roles (
  user_id VARCHAR(64) NOT NULL,
  role_id VARCHAR(64) NOT NULL,
  assigned_by TEXT,
  assigned_at TEXT NOT NULL,
  PRIMARY KEY (user_id, role_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE user_permissions (
  user_id VARCHAR(64) NOT NULL,
  permission_key VARCHAR(64) NOT NULL,
  granted INT NOT NULL,
  assigned_by TEXT,
  assigned_at TEXT NOT NULL,
  reason TEXT,
  expires_at VARCHAR(255),
  PRIMARY KEY (user_id, permission_key),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (permission_key) REFERENCES permissions(`key`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE user_companies (
  user_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64) NOT NULL,
  relationship TEXT NOT NULL
                  CHECK (relationship IN ('owner','member','assigned','readonly')),
  is_default INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  PRIMARY KEY (user_id, company_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE sessions (
  id VARCHAR(64) PRIMARY KEY,
  user_id VARCHAR(64) NOT NULL,
  tenant_id TEXT,
  token_hash TEXT NOT NULL UNIQUE,
  device_id TEXT,
  ip TEXT,
  user_agent TEXT,
  active_company_id TEXT,
  twofa_satisfied INT NOT NULL DEFAULT 0,
  step_up_at TEXT,
  created_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
