-- -------------------------------------------------------------------------
CREATE TABLE login_events (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(255),
  user_id VARCHAR(255),
  email TEXT,
  result TEXT NOT NULL
                  CHECK (result IN ('success','bad_password','unknown_user','locked','twofa_required','twofa_failed','ip_blocked','device_blocked','suspended')),
  ip TEXT,
  user_agent TEXT,
  device_id TEXT,
  anomaly TEXT,
  created_at VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ip_allowlist (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  cidr TEXT NOT NULL,
  label TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE security_policies (
  tenant_id VARCHAR(64) PRIMARY KEY,
  enforce_2fa INT NOT NULL DEFAULT 0,
  enforce_2fa_roles TEXT,
  ip_allowlist_enabled INT NOT NULL DEFAULT 0,
  session_ttl_hours INT NOT NULL DEFAULT 12,
  idle_timeout_minutes INT NOT NULL DEFAULT 60,
  password_min_length INT NOT NULL DEFAULT 10,
  password_require_mixed INT NOT NULL DEFAULT 1,
  password_expiry_days INT NOT NULL DEFAULT 0,
  max_failed_logins INT NOT NULL DEFAULT 5,
  lockout_minutes INT NOT NULL DEFAULT 15,
  device_approval INT NOT NULL DEFAULT 0,
  anomaly_alerts INT NOT NULL DEFAULT 1,
  step_up_for_sensitive INT NOT NULL DEFAULT 0,
  updated_by TEXT,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE clients (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64) NOT NULL,
  branch_id VARCHAR(64),
  client_code VARCHAR(255) NOT NULL,
  display_name TEXT NOT NULL,
  primary_contact_name TEXT,
  primary_contact_email TEXT,
  primary_contact_phone TEXT,
  assigned_executive_id VARCHAR(64),
  assigned_manager_id VARCHAR(64),
  onboarding_status TEXT NOT NULL
                        CHECK (onboarding_status IN ('pending','profile','documents','active')),
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active','inactive','at_risk','churned','archived')),
  health_score INT,
  source TEXT,
  utm_json TEXT,
  tags_json TEXT,
  notes TEXT,
  sla_hours INT NOT NULL DEFAULT 48,
  billing_day INT NOT NULL DEFAULT 1,
  is_demo INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  UNIQUE (tenant_id, client_code),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_executive_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_manager_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE client_contacts (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64),
  name TEXT NOT NULL,
  email TEXT,
  phone VARCHAR(255),
  designation TEXT,
  is_primary INT NOT NULL DEFAULT 0,
  whatsapp_opt_in INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE document_types (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  `key` VARCHAR(255) NOT NULL,
  name TEXT NOT NULL,
  category TEXT NOT NULL
                      CHECK (category IN ('gst','sales','purchase','banking','expense','payment','tds','payroll','returns','tax','statutory','other')),
  description TEXT,
  periodicity TEXT NOT NULL
                      CHECK (periodicity IN ('monthly','quarterly','yearly','one_time','ad_hoc')),
  is_required INT NOT NULL DEFAULT 1,
  accepts_mime TEXT,
  max_bytes INT,
  ocr_profile TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  is_active INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  tenant_id_k VARCHAR(64) AS (IFNULL(tenant_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE filing_periods (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  period_type VARCHAR(255) NOT NULL CHECK (period_type IN ('monthly','quarterly','yearly')),
  period_key VARCHAR(255) NOT NULL,
  period_start TEXT NOT NULL,
  period_end TEXT NOT NULL,
  due_date VARCHAR(255),
  status VARCHAR(255) NOT NULL DEFAULT 'collecting'
                      CHECK (status IN ('collecting','under_review','query_raised','awaiting_client','verified','calculated','pending_approval','approved','client_review','signed_off','paid','filed','archived','rejected')),
  documents_expected INT NOT NULL DEFAULT 0,
  documents_received INT NOT NULL DEFAULT 0,
  documents_verified INT NOT NULL DEFAULT 0,
  locked_at TEXT,
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (client_id, period_type, period_key),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE documents (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  filing_period_id VARCHAR(64),
  document_type_id VARCHAR(64) NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  period_key TEXT,
  current_version_id TEXT,
  version_count INT NOT NULL DEFAULT 1,
  status VARCHAR(255) NOT NULL DEFAULT 'submitted'
                        CHECK (status IN ('draft','submitted','under_review','query_raised','awaiting_client','verified','rejected','approved','archived')),
  priority TEXT NOT NULL
                        CHECK (priority IN ('low','normal','high','urgent')),
  assigned_to VARCHAR(64),
  verified_by VARCHAR(64),
  verified_at TEXT,
  rejected_reason TEXT,
  is_locked INT NOT NULL DEFAULT 0,
  locked_by TEXT,
  locked_at TEXT,
  source TEXT NOT NULL
                        CHECK (source IN ('portal','mobile','whatsapp','email','drive','dropbox','onedrive','api','zip','gps_visit')),
  from_zip_batch_id TEXT,
  ocr_status TEXT NOT NULL
                        CHECK (ocr_status IN ('none','queued','processing','done','failed','skipped')),
  ai_precheck_status TEXT NOT NULL
                        CHECK (ai_precheck_status IN ('none','queued','processing','clean','flagged','failed','skipped')),
  ai_confidence DOUBLE,
  sla_due_at TEXT,
  submitted_at TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE SET NULL,
  FOREIGN KEY (document_type_id) REFERENCES document_types(id),
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (verified_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE document_versions (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64) NOT NULL,
  version_no INT NOT NULL,
  storage_key TEXT NOT NULL,
  file_name TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INT NOT NULL,
  checksum_sha256 TEXT,
  page_count INT,
  uploaded_by VARCHAR(64),
  upload_note TEXT,
  replaces_version_id TEXT,
  is_current INT NOT NULL DEFAULT 1,
  scan_status TEXT NOT NULL
                    CHECK (scan_status IN ('pending','clean','infected','skipped','failed')),
  created_at TEXT NOT NULL,
  UNIQUE (document_id, version_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (uploaded_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE upload_batches (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  filing_period_id VARCHAR(64),
  kind TEXT NOT NULL CHECK (kind IN ('zip','multi','sync')),
  archive_name TEXT,
  archive_key TEXT,
  total_entries INT NOT NULL DEFAULT 0,
  extracted_count INT NOT NULL DEFAULT 0,
  skipped_count INT NOT NULL DEFAULT 0,
  failed_count INT NOT NULL DEFAULT 0,
  status TEXT NOT NULL
                    CHECK (status IN ('processing','completed','partial','failed')),
  report_json TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  completed_at TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE document_comments (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64) NOT NULL,
  version_id VARCHAR(64),
  author_id VARCHAR(64),
  body TEXT NOT NULL,
  visibility TEXT NOT NULL
                  CHECK (visibility IN ('shared','internal')),
  anchor_json TEXT,
  created_at VARCHAR(255) NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (version_id) REFERENCES document_versions(id) ON DELETE SET NULL,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE verification_records (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64) NOT NULL,
  version_id VARCHAR(64),
  verifier_id VARCHAR(64),
  decision TEXT NOT NULL
                      CHECK (decision IN ('approved','rejected','query_raised','changes_requested','reopened','locked','unlocked')),
  reason_code TEXT,
  notes TEXT,
  checklist_json TEXT,
  time_spent_seconds INT,
  sla_met INT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (version_id) REFERENCES document_versions(id) ON DELETE SET NULL,
  FOREIGN KEY (verifier_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE queries (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64),
  filing_period_id VARCHAR(64),
  reference_no VARCHAR(255) NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  category TEXT NOT NULL
                      CHECK (category IN ('document','data','clarification','missing','mismatch','other')),
  priority TEXT NOT NULL
                      CHECK (priority IN ('low','normal','high','urgent')),
  status VARCHAR(255) NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','awaiting_client','client_responded','under_review','resolved','cancelled')),
  raised_by VARCHAR(64),
  assigned_to VARCHAR(64),
  resolved_by VARCHAR(64),
  resolved_at TEXT,
  resolution_note TEXT,
  due_at TEXT,
  first_response_at TEXT,
  reply_count INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE SET NULL,
  FOREIGN KEY (raised_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE query_replies (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  query_id VARCHAR(64) NOT NULL,
  author_id VARCHAR(64),
  author_role TEXT,
  body TEXT NOT NULL,
  visibility TEXT NOT NULL
                    CHECK (visibility IN ('shared','internal')),
  attachments_json TEXT,
  channel TEXT NOT NULL
                    CHECK (channel IN ('portal','email','whatsapp','sms','mobile','voice_note')),
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (query_id) REFERENCES queries(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE checklist_items (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  filing_period_id VARCHAR(64) NOT NULL,
  document_type_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64),
  label TEXT NOT NULL,
  is_required INT NOT NULL DEFAULT 1,
  status TEXT NOT NULL
                      CHECK (status IN ('pending','submitted','under_review','query_raised','verified','rejected','waived')),
  waived_reason TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE CASCADE,
  FOREIGN KEY (document_type_id) REFERENCES document_types(id),
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE tax_rules (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  regime VARCHAR(255) NOT NULL CHECK (regime IN ('gst','tds','tcs','cess')),
  code VARCHAR(255) NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  hsn_sac TEXT,
  section_code TEXT,
  rate_pct DOUBLE NOT NULL DEFAULT 0,
  cgst_pct DOUBLE NOT NULL DEFAULT 0,
  sgst_pct DOUBLE NOT NULL DEFAULT 0,
  igst_pct DOUBLE NOT NULL DEFAULT 0,
  cess_pct DOUBLE NOT NULL DEFAULT 0,
  threshold_paise INT NOT NULL DEFAULT 0,
  payee_type TEXT,
  effective_from VARCHAR(255) NOT NULL,
  effective_to TEXT,
  is_verified INT NOT NULL DEFAULT 1,
  source_note TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE tax_computations (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  filing_period_id VARCHAR(64) NOT NULL,
  regime VARCHAR(255) NOT NULL CHECK (regime IN ('gst','tds')),
  period_type TEXT NOT NULL CHECK (period_type IN ('monthly','quarterly','yearly')),
  period_key VARCHAR(255) NOT NULL,
  taxable_value_paise INT NOT NULL DEFAULT 0,
  cgst_paise INT NOT NULL DEFAULT 0,
  sgst_paise INT NOT NULL DEFAULT 0,
  igst_paise INT NOT NULL DEFAULT 0,
  cess_paise INT NOT NULL DEFAULT 0,
  total_tax_paise INT NOT NULL DEFAULT 0,
  itc_taxable_paise INT NOT NULL DEFAULT 0,
  itc_cgst_paise INT NOT NULL DEFAULT 0,
  itc_sgst_paise INT NOT NULL DEFAULT 0,
  itc_igst_paise INT NOT NULL DEFAULT 0,
  itc_cess_paise INT NOT NULL DEFAULT 0,
  itc_total_paise INT NOT NULL DEFAULT 0,
  net_payable_paise INT NOT NULL DEFAULT 0,
  tds_base_paise INT NOT NULL DEFAULT 0,
  tds_deducted_paise INT NOT NULL DEFAULT 0,
  tds_deposited_paise INT NOT NULL DEFAULT 0,
  status TEXT NOT NULL
                          CHECK (status IN ('draft','computed','stale','superseded','final')),
  source_document_count INT NOT NULL DEFAULT 0,
  line_count INT NOT NULL DEFAULT 0,
  warnings_json TEXT,
  computed_by VARCHAR(64),
  computed_at TEXT,
  engine_version TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE CASCADE,
  FOREIGN KEY (computed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE gst_records (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  computation_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64),
  direction VARCHAR(255) NOT NULL CHECK (direction IN ('outward','inward')),
  supply_type TEXT NOT NULL
                        CHECK (supply_type IN ('intra','inter','export','exempt','nil','non_gst','rcm')),
  invoice_no TEXT,
  invoice_date TEXT,
  counterparty_name TEXT,
  counterparty_gstin TEXT,
  place_of_supply TEXT,
  hsn_sac TEXT,
  description TEXT,
  quantity DOUBLE,
  taxable_value_paise INT NOT NULL DEFAULT 0,
  rate_pct DOUBLE NOT NULL DEFAULT 0,
  cgst_paise INT NOT NULL DEFAULT 0,
  sgst_paise INT NOT NULL DEFAULT 0,
  igst_paise INT NOT NULL DEFAULT 0,
  cess_paise INT NOT NULL DEFAULT 0,
  total_paise INT NOT NULL DEFAULT 0,
  itc_eligible INT NOT NULL DEFAULT 1,
  source TEXT NOT NULL
                        CHECK (source IN ('manual','ocr','import','api','sheet')),
  ocr_confidence DOUBLE,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (computation_id) REFERENCES tax_computations(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE tds_records (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  computation_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64),
  section_code TEXT NOT NULL,
  deductee_name TEXT,
  deductee_pan TEXT,
  payee_type TEXT NOT NULL
                        CHECK (payee_type IN ('individual','huf','company','firm','other')),
  payment_date TEXT,
  amount_paise INT NOT NULL DEFAULT 0,
  rate_pct DOUBLE NOT NULL DEFAULT 0,
  tds_paise INT NOT NULL DEFAULT 0,
  deposited_paise INT NOT NULL DEFAULT 0,
  challan_no TEXT,
  deposited_on TEXT,
  lower_deduction_cert TEXT,
  source TEXT NOT NULL
                        CHECK (source IN ('manual','ocr','import','api','sheet')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (computation_id) REFERENCES tax_computations(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE reports (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64),
  client_id VARCHAR(64),
  filing_period_id VARCHAR(64),
  computation_id VARCHAR(64),
  reference_no VARCHAR(255) NOT NULL,
  type VARCHAR(255) NOT NULL
                      CHECK (type IN ('gst_summary','monthly_tax','quarterly','yearly','tds_summary','revenue','expenses','outstanding_payments','client_report','audit_report','team_performance','call_report','analytics','custom')),
  title TEXT NOT NULL,
  period_type TEXT,
  period_key VARCHAR(255),
  period_start TEXT,
  period_end TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','pending_approval','approved','rejected','client_review','signed_off','published','archived')),
  totals_json TEXT,
  payload_json TEXT,
  filters_json TEXT,
  narrative TEXT,
  ai_generated INT NOT NULL DEFAULT 0,
  ai_reviewed_by TEXT,
  generated_by VARCHAR(64),
  generated_at TEXT,
  submitted_at TEXT,
  approved_by VARCHAR(64),
  approved_at TEXT,
  rejected_reason TEXT,
  client_signed_off_by VARCHAR(64),
  client_signed_off_at TEXT,
  pdf_key TEXT,
  csv_key TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE SET NULL,
  FOREIGN KEY (computation_id) REFERENCES tax_computations(id) ON DELETE SET NULL,
  FOREIGN KEY (generated_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (approved_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (client_signed_off_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE report_items (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  report_id VARCHAR(64) NOT NULL,
  section TEXT NOT NULL,
  label TEXT NOT NULL,
  value_paise INT,
  value_text TEXT,
  value_number DOUBLE,
  unit TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  meta_json TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE approvals (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  entity_type VARCHAR(255) NOT NULL,
  entity_id VARCHAR(255) NOT NULL,
  stage TEXT NOT NULL
                    CHECK (stage IN ('executive','manager','admin','client')),
  status VARCHAR(255) NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','approved','rejected','withdrawn','skipped')),
  requested_by VARCHAR(64),
  requested_at TEXT NOT NULL,
  assignee_id VARCHAR(64),
  decided_by VARCHAR(64),
  decided_at TEXT,
  comment TEXT,
  due_at TEXT,
  sequence INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (requested_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (assignee_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (decided_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE tasks (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64),
  client_id VARCHAR(64),
  filing_period_id VARCHAR(64),
  title TEXT NOT NULL,
  description TEXT,
  type TEXT NOT NULL
                    CHECK (type IN ('general','verification','follow_up','call_follow_up','collection','filing','reconciliation','onboarding','support')),
  status VARCHAR(255) NOT NULL DEFAULT 'todo'
                    CHECK (status IN ('todo','in_progress','blocked','review','done','cancelled')),
  priority TEXT NOT NULL
                    CHECK (priority IN ('low','normal','high','urgent')),
  assigned_to VARCHAR(64),
  created_by VARCHAR(64),
  due_at VARCHAR(255),
  reminder_at TEXT,
  completed_at TEXT,
  source_type TEXT,
  source_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE activities (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id TEXT,
  client_id VARCHAR(255),
  actor_id TEXT,
  actor_name TEXT,
  actor_role TEXT,
  verb TEXT NOT NULL,
  entity_type VARCHAR(255) NOT NULL,
  entity_id VARCHAR(255),
  summary TEXT NOT NULL,
  detail_json TEXT,
  visibility TEXT NOT NULL
                  CHECK (visibility IN ('internal','client','public')),
  icon TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE plans (
  id VARCHAR(64) PRIMARY KEY,
  `key` TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  tagline TEXT,
  monthly_price_paise INT NOT NULL DEFAULT 0,
  yearly_price_paise INT NOT NULL DEFAULT 0,
  currency TEXT NOT NULL,
  max_users INT NOT NULL DEFAULT 1,
  max_companies INT NOT NULL DEFAULT 1,
  storage_gb INT NOT NULL DEFAULT 5,
  max_uploads_month INT NOT NULL DEFAULT 50,
  support_level TEXT NOT NULL
                        CHECK (support_level IN ('email','email_chat','priority')),
  is_public INT NOT NULL DEFAULT 1,
  is_popular INT NOT NULL DEFAULT 0,
  sort_order INT NOT NULL DEFAULT 100,
  trial_days INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE plan_features (
  plan_id VARCHAR(64) NOT NULL,
  feature_key VARCHAR(64) NOT NULL,
  enabled INT NOT NULL DEFAULT 1,
  value TEXT,
  label TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  PRIMARY KEY (plan_id, feature_key),
  FOREIGN KEY (plan_id) REFERENCES plans(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE subscriptions (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  plan_id VARCHAR(64) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                        CHECK (status IN ('trialing','active','past_due','paused','cancelled','expired')),
  billing_cycle TEXT NOT NULL
                        CHECK (billing_cycle IN ('monthly','yearly')),
  seats INT NOT NULL DEFAULT 1,
  unit_price_paise INT NOT NULL DEFAULT 0,
  current_period_start TEXT NOT NULL,
  current_period_end VARCHAR(255) NOT NULL,
  trial_ends_at TEXT,
  auto_renew INT NOT NULL DEFAULT 1,
  cancel_at_period_end INT NOT NULL DEFAULT 0,
  cancelled_at TEXT,
  cancellation_reason TEXT,
  gateway TEXT,
  gateway_subscription_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (plan_id) REFERENCES plans(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE subscription_usage (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  metric VARCHAR(255) NOT NULL,
  period_key VARCHAR(255) NOT NULL,
  value INT NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, metric, period_key),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE add_ons (
  id VARCHAR(64) PRIMARY KEY,
  `key` TEXT NOT NULL UNIQUE,
  number INT NOT NULL,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  category_no INT NOT NULL,
  description TEXT NOT NULL,
  business_benefit TEXT,
  workflow TEXT,
  features_json TEXT NOT NULL,
  ui_screens_json TEXT,
  user_roles_json TEXT,
  apis_required_json TEXT,
  provider_keys_json TEXT,
  best_plan TEXT NOT NULL,
  best_plan_keys_json TEXT,
  monthly_price_paise INT NOT NULL,
  setup_fee_paise INT NOT NULL,
  feature_keys_json TEXT,
  icon TEXT,
  accent TEXT,
  requires_credentials INT NOT NULL DEFAULT 1,
  is_available INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE add_on_subscriptions (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  add_on_id VARCHAR(64) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active','trialing','suspended','cancelled','pending_payment')),
  activated_at TEXT NOT NULL,
  activated_by VARCHAR(64),
  deactivated_at TEXT,
  deactivated_by TEXT,
  billing_cycle TEXT NOT NULL
                        CHECK (billing_cycle IN ('monthly','yearly')),
  monthly_price_paise INT NOT NULL,
  setup_fee_paise INT NOT NULL DEFAULT 0,
  setup_fee_charged INT NOT NULL DEFAULT 0,
  current_period_start TEXT,
  current_period_end TEXT,
  config_json TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, add_on_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (add_on_id) REFERENCES add_ons(id) ON DELETE CASCADE,
  FOREIGN KEY (activated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE add_on_usage (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  add_on_id VARCHAR(64) NOT NULL,
  metric VARCHAR(255) NOT NULL,
  period_key VARCHAR(255) NOT NULL,
  value INT NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, add_on_id, metric, period_key),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (add_on_id) REFERENCES add_ons(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE invoices (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  company_id VARCHAR(64),
  subscription_id VARCHAR(64),
  filing_period_id VARCHAR(64),
  invoice_no VARCHAR(255) NOT NULL,
  direction TEXT NOT NULL
                        CHECK (direction IN ('platform_to_tenant','tenant_to_client')),
  kind TEXT NOT NULL
                        CHECK (kind IN ('subscription','addon','setup','service','adjustment','credit_note')),
  status VARCHAR(255) NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft','issued','sent','partially_paid','paid','overdue','void','refunded')),
  currency TEXT NOT NULL,
  subtotal_paise INT NOT NULL DEFAULT 0,
  discount_paise INT NOT NULL DEFAULT 0,
  tax_paise INT NOT NULL DEFAULT 0,
  cgst_paise INT NOT NULL DEFAULT 0,
  sgst_paise INT NOT NULL DEFAULT 0,
  igst_paise INT NOT NULL DEFAULT 0,
  total_paise INT NOT NULL DEFAULT 0,
  amount_paid_paise INT NOT NULL DEFAULT 0,
  amount_due_paise INT NOT NULL DEFAULT 0,
  issue_date TEXT NOT NULL,
  due_date VARCHAR(255) NOT NULL,
  paid_at TEXT,
  notes TEXT,
  terms TEXT,
  billing_name TEXT,
  billing_email TEXT,
  billing_gstin TEXT,
  billing_address TEXT,
  place_of_supply TEXT,
  pdf_key TEXT,
  reminder_count INT NOT NULL DEFAULT 0,
  last_reminder_at TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, invoice_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL,
  FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL,
  FOREIGN KEY (filing_period_id) REFERENCES filing_periods(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE invoice_items (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  invoice_id VARCHAR(64) NOT NULL,
  description TEXT NOT NULL,
  hsn_sac TEXT,
  quantity DOUBLE NOT NULL DEFAULT 1,
  unit_price_paise INT NOT NULL DEFAULT 0,
  discount_paise INT NOT NULL DEFAULT 0,
  tax_rate_pct DOUBLE NOT NULL DEFAULT 18,
  tax_paise INT NOT NULL DEFAULT 0,
  amount_paise INT NOT NULL DEFAULT 0,
  source_type TEXT,
  source_id TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE payments (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  invoice_id VARCHAR(64),
  client_id VARCHAR(64),
  subscription_id VARCHAR(64),
  reference_no VARCHAR(255) NOT NULL,
  gateway TEXT NOT NULL
                        CHECK (gateway IN ('razorpay','stripe','cashfree','phonepe','manual','offline')),
  method TEXT CHECK (method IN ('upi','credit_card','debit_card','net_banking','wallet','emi','bank_transfer','cash','cheque',NULL)),
  amount_paise INT NOT NULL,
  currency TEXT NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('created','pending','authorized','success','failed','cancelled','refunded','partially_refunded','disputed')),
  gateway_order_id VARCHAR(255),
  gateway_payment_id TEXT,
  gateway_signature TEXT,
  idempotency_key VARCHAR(255),
  failure_code TEXT,
  failure_reason TEXT,
  refunded_paise INT NOT NULL DEFAULT 0,
  retry_count INT NOT NULL DEFAULT 0,
  receipt_no TEXT,
  receipt_key TEXT,
  paid_at TEXT,
  initiated_by TEXT,
  notes_json TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  idempotency_key_k VARCHAR(64) AS (IFNULL(idempotency_key, '~platform')) STORED,
  UNIQUE (tenant_id, reference_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE SET NULL,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE payment_transactions (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  payment_id VARCHAR(64) NOT NULL,
  kind TEXT NOT NULL
                      CHECK (kind IN ('order_created','authorize','capture','fail','refund','chargeback','verify','webhook')),
  status TEXT NOT NULL,
  amount_paise INT NOT NULL DEFAULT 0,
  gateway_reference TEXT,
  request_json TEXT,
  response_json TEXT,
  error_code TEXT,
  error_message TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (payment_id) REFERENCES payments(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE webhook_events (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id TEXT,
  source VARCHAR(255) NOT NULL,
  event_id VARCHAR(255),
  event_type TEXT,
  signature_status TEXT NOT NULL
                      CHECK (signature_status IN ('unverified','valid','invalid','missing_secret')),
  status TEXT NOT NULL
                      CHECK (status IN ('received','processed','ignored','failed','duplicate')),
  payload_json TEXT NOT NULL,
  headers_json TEXT,
  error_message TEXT,
  processed_at TEXT,
  received_at VARCHAR(255) NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  event_id_k VARCHAR(64) AS (IFNULL(event_id, '~platform')) STORED
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE franchise_revenue (
  id VARCHAR(64) PRIMARY KEY,
  franchise_id VARCHAR(64) NOT NULL,
  tenant_id VARCHAR(64) NOT NULL,
  period_key VARCHAR(255) NOT NULL,
  gross_paise INT NOT NULL DEFAULT 0,
  share_pct DOUBLE NOT NULL,
  share_paise INT NOT NULL DEFAULT 0,
  status TEXT NOT NULL
                      CHECK (status IN ('accrued','approved','paid','disputed')),
  settled_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (franchise_id, tenant_id, period_key),
  FOREIGN KEY (franchise_id) REFERENCES franchises(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE notification_templates (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  trigger_key VARCHAR(255) NOT NULL,
  channel VARCHAR(255) NOT NULL
                    CHECK (channel IN ('email','sms','whatsapp','in_app','push')),
  name TEXT NOT NULL,
  subject TEXT,
  body TEXT NOT NULL,
  provider_template_id TEXT,
  variables_json TEXT,
  is_active INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  tenant_id_k VARCHAR(64) AS (IFNULL(tenant_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE notification_preferences (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64),
  trigger_key VARCHAR(255) NOT NULL DEFAULT '*',
  email_enabled INT NOT NULL DEFAULT 1,
  sms_enabled INT NOT NULL DEFAULT 0,
  whatsapp_enabled INT NOT NULL DEFAULT 0,
  in_app_enabled INT NOT NULL DEFAULT 1,
  push_enabled INT NOT NULL DEFAULT 1,
  quiet_hours_start TEXT,
  quiet_hours_end TEXT,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, user_id, trigger_key),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE notifications (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  trigger_key TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  severity TEXT NOT NULL
                  CHECK (severity IN ('info','success','warning','danger')),
  icon TEXT,
  link_path TEXT,
  entity_type TEXT,
  entity_id TEXT,
  read_at VARCHAR(255),
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE message_deliveries (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  channel VARCHAR(255) NOT NULL CHECK (channel IN ('email','sms','whatsapp','push','in_app')),
  provider TEXT,
  trigger_key TEXT,
  template_id TEXT,
  to_user_id TEXT,
  to_address TEXT NOT NULL,
  subject TEXT,
  body TEXT,
  attachments_json TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'queued'
                      CHECK (status IN ('queued','sending','sent','delivered','read','opened','clicked','failed','bounced','skipped','not_configured')),
  provider_message_id TEXT,
  error_code TEXT,
  error_message TEXT,
  attempts INT NOT NULL DEFAULT 0,
  opened_at TEXT,
  clicked_at TEXT,
  delivered_at TEXT,
  entity_type TEXT,
  entity_id TEXT,
  client_id VARCHAR(255),
  campaign_id TEXT,
  created_at VARCHAR(255) NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE automation_rules (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  trigger_key VARCHAR(255) NOT NULL,
  conditions_json TEXT,
  actions_json TEXT NOT NULL,
  channel TEXT,
  delay_minutes INT NOT NULL DEFAULT 0,
  is_active INT NOT NULL DEFAULT 1,
  last_fired_at TEXT,
  fire_count INT NOT NULL DEFAULT 0,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE whatsapp_templates (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  language VARCHAR(255) NOT NULL DEFAULT 'en',
  category TEXT NOT NULL
                        CHECK (category IN ('UTILITY','MARKETING','AUTHENTICATION')),
  header_text TEXT,
  body_text TEXT NOT NULL,
  footer_text TEXT,
  buttons_json TEXT,
  variables_json TEXT,
  approval_status TEXT NOT NULL
                        CHECK (approval_status IN ('draft','pending','approved','rejected','disabled')),
  provider_template_id TEXT,
  rejection_reason TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, name, language),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE chatbot_flows (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  trigger_keywords_json TEXT,
  nodes_json TEXT NOT NULL,
  entry_node_id TEXT,
  is_active INT NOT NULL DEFAULT 0,
  fallback_to_human INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE voice_notes (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  entity_type VARCHAR(255),
  entity_id VARCHAR(255),
  author_id VARCHAR(64),
  storage_key TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  duration_seconds INT NOT NULL DEFAULT 0,
  size_bytes INT NOT NULL DEFAULT 0,
  transcript TEXT,
  transcript_status TEXT NOT NULL
                      CHECK (transcript_status IN ('pending','processing','done','failed','not_configured','skipped')),
  transcript_lang TEXT,
  transcript_confidence DOUBLE,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE support_tickets (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  company_id VARCHAR(64),
  ticket_no VARCHAR(255) NOT NULL,
  subject TEXT NOT NULL,
  description TEXT NOT NULL,
  category TEXT NOT NULL
                      CHECK (category IN ('general','technical','billing','document','filing','account','feature_request','bug','other')),
  priority TEXT NOT NULL
                      CHECK (priority IN ('low','normal','high','urgent')),
  status VARCHAR(255) NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','in_progress','waiting_customer','waiting_internal','resolved','closed','reopened')),
  raised_by VARCHAR(64),
  assigned_to VARCHAR(64),
  channel TEXT NOT NULL
                      CHECK (channel IN ('portal','email','whatsapp','phone','chat','api')),
  first_response_at TEXT,
  resolved_at TEXT,
  closed_at TEXT,
  resolution TEXT,
  satisfaction_rating INT,
  sla_due_at TEXT,
  sla_breached INT NOT NULL DEFAULT 0,
  reopen_count INT NOT NULL DEFAULT 0,
  message_count INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, ticket_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL,
  FOREIGN KEY (raised_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ticket_messages (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  ticket_id VARCHAR(64) NOT NULL,
  author_id VARCHAR(64),
  author_name TEXT,
  author_kind TEXT NOT NULL
                      CHECK (author_kind IN ('agent','client','system')),
  body TEXT NOT NULL,
  visibility TEXT NOT NULL
                      CHECK (visibility IN ('shared','internal')),
  attachments_json TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE integrations (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  provider VARCHAR(255) NOT NULL,
  category VARCHAR(255) NOT NULL,
  add_on_key TEXT,
  display_name TEXT NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'not_connected'
                        CHECK (status IN ('not_connected','pending','connected','error','disabled','expired')),
  config_json TEXT,
  credential_ref TEXT,
  encrypted_secret TEXT,
  last_test_at TEXT,
  last_test_ok INT,
  last_test_message TEXT,
  last_sync_at TEXT,
  last_error TEXT,
  connected_by VARCHAR(64),
  connected_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, provider),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (connected_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE oauth_connections (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  integration_id VARCHAR(64),
  provider VARCHAR(255) NOT NULL,
  account_email TEXT,
  account_id VARCHAR(255),
  scopes TEXT,
  access_token_enc TEXT,
  refresh_token_enc TEXT,
  token_type TEXT,
  expires_at TEXT,
  status TEXT NOT NULL
                      CHECK (status IN ('active','expired','revoked','error')),
  connected_by VARCHAR(64),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, provider, account_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (integration_id) REFERENCES integrations(id) ON DELETE CASCADE,
  FOREIGN KEY (connected_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE oauth_states (
  state VARCHAR(64) PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  redirect_path TEXT,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE integration_sync_logs (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  integration_id VARCHAR(64),
  provider VARCHAR(255) NOT NULL,
  direction TEXT NOT NULL CHECK (direction IN ('inbound','outbound','bidirectional')),
  operation TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('started','success','partial','failed','skipped')),
  records_in INT NOT NULL DEFAULT 0,
  records_out INT NOT NULL DEFAULT 0,
  records_failed INT NOT NULL DEFAULT 0,
  detail_json TEXT,
  error_message TEXT,
  duration_ms INT,
  started_at VARCHAR(255) NOT NULL,
  finished_at TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (integration_id) REFERENCES integrations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE field_mappings (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  integration_id VARCHAR(64),
  source_key TEXT NOT NULL,
  source_label TEXT,
  target_entity TEXT NOT NULL
                      CHECK (target_entity IN ('lead','client','company','contact','document','task')),
  target_field TEXT NOT NULL,
  transform TEXT,
  is_required INT NOT NULL DEFAULT 0,
  default_value TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (integration_id) REFERENCES integrations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE campaigns (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  external_id TEXT,
  source VARCHAR(255) NOT NULL
                      CHECK (source IN ('meta_ads','google_ads','website','google_form','sheet','referral','manual','other')),
  name TEXT NOT NULL,
  platform TEXT,
  status TEXT NOT NULL
                      CHECK (status IN ('active','paused','completed','archived')),
  spend_paise INT NOT NULL DEFAULT 0,
  lead_count INT NOT NULL DEFAULT 0,
  converted_count INT NOT NULL DEFAULT 0,
  started_at TEXT,
  ended_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE leads (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  campaign_id VARCHAR(64),
  external_id VARCHAR(255),
  source VARCHAR(255) NOT NULL DEFAULT 'manual'
                      CHECK (source IN ('meta_ads','google_form','website_form','sheet','whatsapp','call','referral','manual','api','other')),
  full_name TEXT NOT NULL,
  email VARCHAR(255),
  phone VARCHAR(255),
  company_name TEXT,
  city TEXT,
  message TEXT,
  payload_json TEXT,
  utm_source TEXT,
  utm_medium TEXT,
  utm_campaign TEXT,
  utm_term TEXT,
  utm_content TEXT,
  page_url TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'new'
                      CHECK (status IN ('new','contacted','qualified','proposal','won','lost','duplicate','spam')),
  assigned_to VARCHAR(64),
  assigned_at TEXT,
  duplicate_of VARCHAR(64),
  merged_into VARCHAR(64),
  converted_client_id VARCHAR(64),
  converted_at TEXT,
  score INT,
  tags_json TEXT,
  last_contacted_at TEXT,
  created_at VARCHAR(255) NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  external_id_k VARCHAR(64) AS (IFNULL(external_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (duplicate_of) REFERENCES leads(id) ON DELETE SET NULL,
  FOREIGN KEY (merged_into) REFERENCES leads(id) ON DELETE SET NULL,
  FOREIGN KEY (converted_client_id) REFERENCES clients(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE lead_assignment_rules (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  priority INT NOT NULL DEFAULT 100,
  conditions_json TEXT,
  strategy TEXT NOT NULL
                    CHECK (strategy IN ('round_robin','least_loaded','specific_user','branch_manager')),
  target_user_id VARCHAR(64),
  pool_json TEXT,
  last_assigned_index INT NOT NULL DEFAULT 0,
  is_active INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE webhook_endpoints (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  kind TEXT NOT NULL
                    CHECK (kind IN ('website_form','google_form','sheet','custom')),
  secret_hash TEXT,
  target_entity TEXT NOT NULL,
  is_active INT NOT NULL DEFAULT 1,
  request_count INT NOT NULL DEFAULT 0,
  last_request_at TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ocr_extractions (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64) NOT NULL,
  version_id VARCHAR(64),
  profile TEXT NOT NULL,
  provider TEXT NOT NULL,
  status TEXT NOT NULL
                      CHECK (status IN ('queued','processing','done','failed','not_configured')),
  overall_confidence DOUBLE,
  fields_json TEXT,
  raw_text TEXT,
  review_status VARCHAR(255) NOT NULL DEFAULT 'pending'
                      CHECK (review_status IN ('pending','accepted','edited','rejected')),
  reviewed_by VARCHAR(64),
  reviewed_at TEXT,
  applied_to_records INT NOT NULL DEFAULT 0,
  error_message TEXT,
  duration_ms INT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (version_id) REFERENCES document_versions(id) ON DELETE SET NULL,
  FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ai_verifications (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64) NOT NULL,
  version_id VARCHAR(64),
  status TEXT NOT NULL
                      CHECK (status IN ('queued','processing','clean','flagged','failed','not_configured')),
  confidence DOUBLE,
  checks_json TEXT,
  flags_json TEXT,
  flag_count INT NOT NULL DEFAULT 0,
  recommendation TEXT CHECK (recommendation IN ('pre_approve','review','reject',NULL)),
  provider TEXT,
  error_message TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (version_id) REFERENCES document_versions(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ai_conversations (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  kind TEXT NOT NULL
                  CHECK (kind IN ('tax_assistant','ask_your_data','call_summary','report_draft')),
  title TEXT,
  context_json TEXT,
  message_count INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ai_messages (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  conversation_id VARCHAR(64) NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('user','assistant','system')),
  content TEXT NOT NULL,
  citations_json TEXT,
  is_verified_data INT NOT NULL DEFAULT 0,
  disclaimer TEXT,
  model TEXT,
  tokens_in INT,
  tokens_out INT,
  latency_ms INT,
  error_message TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ai_insights (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  kind TEXT NOT NULL
                  CHECK (kind IN ('digest','churn_risk','revenue_forecast','workload_forecast','anomaly','opportunity')),
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  severity TEXT NOT NULL
                  CHECK (severity IN ('info','success','warning','danger')),
  entity_type TEXT,
  entity_id TEXT,
  metrics_json TEXT,
  confidence DOUBLE,
  period_key TEXT,
  generated_by TEXT NOT NULL
                  CHECK (generated_by IN ('rules','llm')),
  model TEXT,
  acknowledged_by TEXT,
  acknowledged_at TEXT,
  dismissed_at TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE esign_requests (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  document_id VARCHAR(64),
  report_id VARCHAR(64),
  reference_no VARCHAR(255) NOT NULL,
  title TEXT NOT NULL,
  provider TEXT NOT NULL
                      CHECK (provider IN ('digio','leegality','other')),
  method TEXT NOT NULL
                      CHECK (method IN ('aadhaar_esign','dsc','electronic')),
  status TEXT NOT NULL
                      CHECK (status IN ('draft','sent','partially_signed','signed','declined','expired','failed','not_configured')),
  source_key TEXT,
  signed_key TEXT,
  provider_request_id TEXT,
  sequential INT NOT NULL DEFAULT 1,
  expires_at TEXT,
  completed_at TEXT,
  created_by VARCHAR(64),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, reference_no),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL,
  FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE SET NULL,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE esign_signers (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  request_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  sequence INT NOT NULL DEFAULT 1,
  status TEXT NOT NULL
                    CHECK (status IN ('pending','sent','viewed','signed','declined','expired')),
  signed_at TEXT,
  declined_reason TEXT,
  ip TEXT,
  provider_signer_id TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (request_id) REFERENCES esign_requests(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE storage_folder_maps (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  integration_id VARCHAR(64) NOT NULL,
  provider VARCHAR(255) NOT NULL CHECK (provider IN ('google_drive','dropbox','onedrive')),
  scope_type TEXT NOT NULL
                      CHECK (scope_type IN ('tenant','company','client')),
  scope_id TEXT,
  remote_folder_id TEXT,
  remote_path TEXT NOT NULL,
  auto_sync INT NOT NULL DEFAULT 1,
  sync_on TEXT NOT NULL
                      CHECK (sync_on IN ('upload','verified','approved')),
  preserve_versions INT NOT NULL DEFAULT 1,
  last_sync_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (integration_id) REFERENCES integrations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE storage_sync_items (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  map_id VARCHAR(64) NOT NULL,
  document_id VARCHAR(64),
  version_id VARCHAR(64),
  remote_file_id TEXT,
  remote_path TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','syncing','synced','failed','skipped')),
  error_message TEXT,
  synced_at TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (map_id) REFERENCES storage_folder_maps(id) ON DELETE CASCADE,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (version_id) REFERENCES document_versions(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE calendar_events (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  owner_id VARCHAR(64),
  title TEXT NOT NULL,
  description TEXT,
  kind TEXT NOT NULL
                      CHECK (kind IN ('meeting','due_date','reminder','visit','call','filing_deadline')),
  location TEXT,
  starts_at VARCHAR(255) NOT NULL,
  ends_at TEXT NOT NULL,
  all_day INT NOT NULL DEFAULT 0,
  attendees_json TEXT,
  reminder_minutes INT NOT NULL DEFAULT 30,
  status TEXT NOT NULL
                      CHECK (status IN ('tentative','confirmed','cancelled')),
  provider TEXT CHECK (provider IN ('google','outlook',NULL)),
  provider_event_id TEXT,
  sync_status TEXT NOT NULL
                      CHECK (sync_status IN ('local','pending','synced','failed','not_configured')),
  source_type TEXT,
  source_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE api_keys (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  key_prefix TEXT NOT NULL,
  key_hash TEXT NOT NULL UNIQUE,
  scopes_json TEXT NOT NULL,
  rate_limit_per_min INT NOT NULL DEFAULT 60,
  allowed_ips_json TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','revoked','expired')),
  last_used_at TEXT,
  request_count INT NOT NULL DEFAULT 0,
  expires_at TEXT,
  created_by VARCHAR(64),
  created_at TEXT NOT NULL,
  revoked_at TEXT,
  revoked_by TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE api_usage (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  api_key_id VARCHAR(64),
  method TEXT NOT NULL,
  path TEXT NOT NULL,
  status_code INT NOT NULL,
  duration_ms INT,
  ip TEXT,
  user_agent TEXT,
  error_code TEXT,
  bucket_hour VARCHAR(255) NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (api_key_id) REFERENCES api_keys(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE telephony_settings (
  tenant_id VARCHAR(64) PRIMARY KEY,
  provider TEXT NOT NULL
                          CHECK (provider IN ('exotel','knowlarity','myoperator','twilio','plivo','ringcentral','aircall')),
  status TEXT NOT NULL
                          CHECK (status IN ('not_connected','connected','error','disabled')),
  caller_id TEXT,
  virtual_numbers_json TEXT,
  recording_mode TEXT NOT NULL
                          CHECK (recording_mode IN ('automatic','manual','disabled')),
  recording_retention_days INT NOT NULL DEFAULT 365,
  transcription_enabled INT NOT NULL DEFAULT 0,
  ai_summary_enabled INT NOT NULL DEFAULT 0,
  sentiment_enabled INT NOT NULL DEFAULT 0,
  auto_create_task INT NOT NULL DEFAULT 1,
  auto_log_activity INT NOT NULL DEFAULT 1,
  ivr_enabled INT NOT NULL DEFAULT 0,
  voicemail_enabled INT NOT NULL DEFAULT 1,
  business_hours_json TEXT,
  webhook_secret_set INT NOT NULL DEFAULT 0,
  last_test_at TEXT,
  last_test_ok INT,
  last_test_message TEXT,
  updated_by TEXT,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE telephony_agents (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  extension TEXT,
  provider_agent_id TEXT,
  direct_number TEXT,
  presence TEXT NOT NULL
                      CHECK (presence IN ('offline','available','busy','on_call','away','dnd')),
  presence_updated_at TEXT,
  is_active INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, user_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_dispositions (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  `key` VARCHAR(255) NOT NULL,
  label TEXT NOT NULL,
  outcome TEXT NOT NULL
                  CHECK (outcome IN ('positive','neutral','negative')),
  requires_follow_up INT NOT NULL DEFAULT 0,
  colour TEXT,
  sort_order INT NOT NULL DEFAULT 100,
  is_active INT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  UNIQUE (tenant_id, `key`),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_tags (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  label VARCHAR(255) NOT NULL,
  colour TEXT,
  usage_count INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  UNIQUE (tenant_id, label),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_records (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  company_id VARCHAR(64),
  client_id VARCHAR(64),
  contact_id VARCHAR(64),
  lead_id VARCHAR(64),
  agent_id VARCHAR(64),
  provider VARCHAR(255) NOT NULL,
  provider_call_id VARCHAR(255),
  direction VARCHAR(255) NOT NULL CHECK (direction IN ('inbound','outbound','internal')),
  from_number TEXT NOT NULL,
  to_number TEXT NOT NULL,
  virtual_number TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'initiated'
                        CHECK (status IN ('initiated','ringing','in_progress','on_hold','completed','missed','busy','no_answer','failed','cancelled','voicemail')),
  answered INT NOT NULL DEFAULT 0,
  started_at TEXT,
  answered_at TEXT,
  ended_at TEXT,
  duration_seconds INT NOT NULL DEFAULT 0,
  talk_seconds INT NOT NULL DEFAULT 0,
  hold_seconds INT NOT NULL DEFAULT 0,
  wait_seconds INT NOT NULL DEFAULT 0,
  is_muted INT NOT NULL DEFAULT 0,
  is_on_hold INT NOT NULL DEFAULT 0,
  is_recording INT NOT NULL DEFAULT 0,
  recording_enabled INT NOT NULL DEFAULT 1,
  transferred_to VARCHAR(64),
  transferred_at TEXT,
  transfer_type TEXT CHECK (transfer_type IN ('warm','cold',NULL)),
  is_conference INT NOT NULL DEFAULT 0,
  conference_id TEXT,
  ivr_flow_id TEXT,
  ivr_path_json TEXT,
  disposition_id VARCHAR(64),
  disposition_key TEXT,
  tags_json TEXT,
  entity_type TEXT,
  entity_id TEXT,
  follow_up_task_id VARCHAR(64),
  follow_up_at TEXT,
  missed_handled INT NOT NULL DEFAULT 0,
  missed_callback_at TEXT,
  cost_paise INT NOT NULL DEFAULT 0,
  quality_rating INT,
  created_at VARCHAR(255) NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  provider_call_id_k VARCHAR(64) AS (IFNULL(provider_call_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (contact_id) REFERENCES client_contacts(id) ON DELETE SET NULL,
  FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE SET NULL,
  FOREIGN KEY (agent_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (transferred_to) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (disposition_id) REFERENCES call_dispositions(id) ON DELETE SET NULL,
  FOREIGN KEY (follow_up_task_id) REFERENCES tasks(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_recordings (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  call_id VARCHAR(64) NOT NULL,
  storage_key TEXT,
  provider_url TEXT,
  mime_type TEXT NOT NULL,
  size_bytes INT NOT NULL DEFAULT 0,
  duration_seconds INT NOT NULL DEFAULT 0,
  status VARCHAR(255) NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','available','archived','deleted','failed','not_configured')),
  waveform_json TEXT,
  retention_until TEXT,
  downloaded_count INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (call_id) REFERENCES call_records(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_notes (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  call_id VARCHAR(64) NOT NULL,
  author_id VARCHAR(64),
  body TEXT NOT NULL,
  is_during_call INT NOT NULL DEFAULT 0,
  created_at VARCHAR(255) NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (call_id) REFERENCES call_records(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_transcripts (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  call_id VARCHAR(64) NOT NULL,
  provider TEXT NOT NULL,
  status TEXT NOT NULL
                      CHECK (status IN ('queued','processing','done','failed','not_configured')),
  language TEXT,
  full_text TEXT,
  segments_json TEXT,
  confidence DOUBLE,
  word_count INT,
  error_message TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (call_id) REFERENCES call_records(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_ai_analysis (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  call_id VARCHAR(64) NOT NULL,
  status TEXT NOT NULL
                      CHECK (status IN ('queued','processing','done','failed','not_configured')),
  summary TEXT,
  key_points_json TEXT,
  action_items_json TEXT,
  sentiment VARCHAR(255) CHECK (sentiment IN ('positive','neutral','negative','mixed',NULL)),
  sentiment_score DOUBLE,
  topics_json TEXT,
  next_step TEXT,
  model TEXT,
  confidence DOUBLE,
  error_message TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (call_id) REFERENCES call_records(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE ivr_flows (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  greeting_text TEXT,
  greeting_key TEXT,
  nodes_json TEXT NOT NULL,
  business_hours_json TEXT,
  after_hours_action TEXT NOT NULL
                      CHECK (after_hours_action IN ('voicemail','message','forward','hangup')),
  is_active INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE voicemails (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  call_id VARCHAR(64),
  client_id VARCHAR(64),
  from_number TEXT NOT NULL,
  to_number TEXT,
  assigned_to VARCHAR(64),
  storage_key TEXT,
  provider_url TEXT,
  duration_seconds INT NOT NULL DEFAULT 0,
  transcript TEXT,
  status VARCHAR(255) NOT NULL DEFAULT 'new'
                      CHECK (status IN ('new','heard','actioned','archived')),
  heard_at TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (call_id) REFERENCES call_records(id) ON DELETE SET NULL,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE call_metrics_daily (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  agent_id VARCHAR(64),
  day VARCHAR(255) NOT NULL,
  total_calls INT NOT NULL DEFAULT 0,
  inbound_calls INT NOT NULL DEFAULT 0,
  outbound_calls INT NOT NULL DEFAULT 0,
  missed_calls INT NOT NULL DEFAULT 0,
  answered_calls INT NOT NULL DEFAULT 0,
  total_duration_sec INT NOT NULL DEFAULT 0,
  avg_duration_sec INT NOT NULL DEFAULT 0,
  positive_count INT NOT NULL DEFAULT 0,
  neutral_count INT NOT NULL DEFAULT 0,
  negative_count INT NOT NULL DEFAULT 0,
  follow_ups_created INT NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, agent_id, day),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE audit_logs (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(255),
  sequence INT NOT NULL,
  actor_id VARCHAR(255),
  actor_name TEXT,
  actor_role TEXT,
  actor_type TEXT NOT NULL
                    CHECK (actor_type IN ('user','system','api_key','webhook','cron','anonymous')),
  action VARCHAR(255) NOT NULL,
  category TEXT NOT NULL,
  entity_type VARCHAR(255),
  entity_id VARCHAR(255),
  entity_label TEXT,
  old_value_json TEXT,
  new_value_json TEXT,
  severity TEXT NOT NULL
                    CHECK (severity IN ('debug','info','notice','warning','critical')),
  result TEXT NOT NULL
                    CHECK (result IN ('success','failure','denied')),
  ip TEXT,
  user_agent TEXT,
  session_id TEXT,
  request_id TEXT,
  metadata_json TEXT,
  prev_hash TEXT,
  hash TEXT NOT NULL,
  retain_until TEXT,
  created_at VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE system_logs (
  id VARCHAR(64) PRIMARY KEY,
  level VARCHAR(255) NOT NULL CHECK (level IN ('debug','info','warn','error','fatal')),
  source TEXT NOT NULL,
  event TEXT NOT NULL,
  message TEXT NOT NULL,
  tenant_id TEXT,
  request_id TEXT,
  path TEXT,
  status_code INT,
  duration_ms INT,
  context_json TEXT,
  stack TEXT,
  created_at VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE backups (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  kind TEXT NOT NULL
                      CHECK (kind IN ('full','database','documents','settings')),
  scope TEXT NOT NULL
                      CHECK (scope IN ('platform','tenant')),
  status TEXT NOT NULL
                      CHECK (status IN ('queued','running','completed','failed','expired','restored')),
  `trigger` TEXT NOT NULL
                      CHECK (`trigger` IN ('manual','scheduled')),
  storage_key TEXT,
  size_bytes INT NOT NULL DEFAULT 0,
  table_count INT NOT NULL DEFAULT 0,
  row_count INT NOT NULL DEFAULT 0,
  document_count INT NOT NULL DEFAULT 0,
  checksum_sha256 TEXT,
  manifest_json TEXT,
  error_message TEXT,
  started_at TEXT,
  completed_at TEXT,
  expires_at TEXT,
  created_by TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE restore_jobs (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  backup_id VARCHAR(64) NOT NULL,
  mode TEXT NOT NULL
                  CHECK (mode IN ('dry_run','restore')),
  status TEXT NOT NULL
                  CHECK (status IN ('queued','running','completed','failed','cancelled')),
  tables_json TEXT,
  report_json TEXT,
  error_message TEXT,
  confirmed_by TEXT,
  started_at TEXT,
  completed_at TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (backup_id) REFERENCES backups(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE attendance (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  branch_id VARCHAR(64),
  day VARCHAR(255) NOT NULL,
  check_in_at TEXT,
  check_in_lat DOUBLE,
  check_in_lng DOUBLE,
  check_in_accuracy DOUBLE,
  check_in_address TEXT,
  check_in_within_geofence INT,
  check_out_at TEXT,
  check_out_lat DOUBLE,
  check_out_lng DOUBLE,
  check_out_address TEXT,
  check_out_within_geofence INT,
  worked_minutes INT NOT NULL DEFAULT 0,
  travel_km DOUBLE NOT NULL DEFAULT 0,
  visit_count INT NOT NULL DEFAULT 0,
  status TEXT NOT NULL
                      CHECK (status IN ('present','half_day','absent','leave','holiday','remote','pending')),
  notes TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (user_id, day),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE gps_visits (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  attendance_id VARCHAR(64),
  user_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  purpose TEXT NOT NULL
                      CHECK (purpose IN ('document_collection','meeting','audit','delivery','other')),
  checked_in_at VARCHAR(255) NOT NULL,
  checked_out_at TEXT,
  latitude DOUBLE NOT NULL,
  longitude DOUBLE NOT NULL,
  accuracy_m DOUBLE,
  address TEXT,
  within_geofence INT,
  distance_from_client_m DOUBLE,
  duration_minutes INT NOT NULL DEFAULT 0,
  notes TEXT,
  documents_collected INT NOT NULL DEFAULT 0,
  photo_key TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (attendance_id) REFERENCES attendance(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE white_label_settings (
  tenant_id VARCHAR(64) PRIMARY KEY,
  enabled INT NOT NULL DEFAULT 0,
  product_name TEXT,
  logo_key TEXT,
  logo_dark_key TEXT,
  favicon_key TEXT,
  app_icon_key TEXT,
  primary_colour TEXT,
  accent_colour TEXT,
  sidebar_style TEXT NOT NULL
                        CHECK (sidebar_style IN ('glass','solid')),
  login_headline TEXT,
  login_subtext TEXT,
  login_image_key TEXT,
  custom_domain TEXT,
  domain_status TEXT NOT NULL
                        CHECK (domain_status IN ('not_configured','pending_dns','verifying','active','failed')),
  domain_verification_token TEXT,
  domain_verified_at TEXT,
  ssl_status TEXT NOT NULL
                        CHECK (ssl_status IN ('none','pending','active','failed')),
  email_from_name TEXT,
  email_from_address TEXT,
  email_footer TEXT,
  sms_sender_id TEXT,
  support_email TEXT,
  support_phone TEXT,
  hide_powered_by INT NOT NULL DEFAULT 0,
  updated_by TEXT,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE settings (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  namespace VARCHAR(255) NOT NULL,
  `key` VARCHAR(255) NOT NULL,
  value_json TEXT NOT NULL,
  value_type TEXT NOT NULL
                  CHECK (value_type IN ('string','number','boolean','json')),
  is_secret INT NOT NULL DEFAULT 0,
  description TEXT,
  updated_by TEXT,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  tenant_id_k VARCHAR(64) AS (IFNULL(tenant_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE feature_flags (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64),
  feature_key VARCHAR(255) NOT NULL,
  enabled INT NOT NULL,
  reason TEXT,
  expires_at TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  tenant_id_k VARCHAR(64) AS (IFNULL(tenant_id, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE saved_views (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64),
  screen VARCHAR(255) NOT NULL,
  name TEXT NOT NULL,
  filters_json TEXT NOT NULL,
  columns_json TEXT,
  sort_json TEXT,
  is_default INT NOT NULL DEFAULT 0,
  is_shared INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE scheduled_reports (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name TEXT NOT NULL,
  report_type TEXT NOT NULL,
  filters_json TEXT,
  format TEXT NOT NULL CHECK (format IN ('csv','pdf','json')),
  frequency TEXT NOT NULL
                      CHECK (frequency IN ('daily','weekly','monthly','quarterly')),
  day_of_week INT,
  day_of_month INT,
  hour_utc INT NOT NULL DEFAULT 3,
  recipients_json TEXT NOT NULL,
  is_active INT NOT NULL DEFAULT 1,
  last_run_at TEXT,
  last_run_status TEXT,
  next_run_at VARCHAR(255),
  run_count INT NOT NULL DEFAULT 0,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE custom_dashboards (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64),
  name TEXT NOT NULL,
  description TEXT,
  widgets_json TEXT NOT NULL,
  is_shared INT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE push_tokens (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  token VARCHAR(255) NOT NULL,
  platform TEXT NOT NULL CHECK (platform IN ('android','ios','web')),
  device_label TEXT,
  app_version TEXT,
  is_active INT NOT NULL DEFAULT 1,
  last_used_at TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (user_id, token),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE offline_captures (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  local_ref VARCHAR(255) NOT NULL,
  document_type_id TEXT,
  file_name TEXT,
  size_bytes INT,
  captured_at TEXT NOT NULL,
  status TEXT NOT NULL
                      CHECK (status IN ('pending','uploading','uploaded','failed','discarded')),
  document_id VARCHAR(64),
  error_message TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (user_id, local_ref),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE rate_limits (
  id VARCHAR(64) PRIMARY KEY,
  scope TEXT NOT NULL,
  window_start TEXT NOT NULL,
  count INT NOT NULL DEFAULT 0,
  expires_at VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE automation_jobs (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  rule_id VARCHAR(64) NOT NULL,
  trigger_key TEXT NOT NULL,
  payload_json TEXT,
  run_after VARCHAR(255) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','running','done','failed','cancelled')),
  attempts INT NOT NULL DEFAULT 0,
  last_error TEXT,
  dedupe_key VARCHAR(255),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  -- Collapses a pair of SQLite partial unique indexes: MySQL treats
  -- NULLs as distinct, which would let two platform rows share a key.
  dedupe_key_k VARCHAR(64) AS (IFNULL(dedupe_key, '~platform')) STORED,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (rule_id) REFERENCES automation_rules(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE automation_runs (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  rule_id VARCHAR(64) NOT NULL,
  trigger_key TEXT NOT NULL,
  status TEXT NOT NULL
                  CHECK (status IN ('fired','skipped','queued','failed')),
  reason TEXT,
  actions_json TEXT,
  error TEXT,
  entity_type TEXT,
  entity_id TEXT,
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (rule_id) REFERENCES automation_rules(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE broadcasts (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  channel TEXT NOT NULL CHECK (channel IN ('whatsapp','sms','email')),
  name TEXT NOT NULL,
  template_id VARCHAR(64),
  body TEXT,
  audience_json TEXT NOT NULL,
  recipient_count INT NOT NULL DEFAULT 0,
  sent_count INT NOT NULL DEFAULT 0,
  delivered_count INT NOT NULL DEFAULT 0,
  failed_count INT NOT NULL DEFAULT 0,
  status VARCHAR(255) NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','queued','scheduled','processing','sending','sent','completed','failed','cancelled')),
  scheduled_at TEXT,
  started_at TEXT,
  completed_at TEXT,
  last_error TEXT,
  created_by VARCHAR(64),
  created_at VARCHAR(255) NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (template_id) REFERENCES whatsapp_templates(id) ON DELETE SET NULL,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE chat_threads (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  channel VARCHAR(255) NOT NULL DEFAULT 'whatsapp' CHECK (channel IN ('whatsapp','sms')),
  client_id VARCHAR(64),
  contact_id VARCHAR(64),
  phone VARCHAR(255) NOT NULL,
  display_name TEXT,
  assigned_to VARCHAR(64),
  status VARCHAR(255) NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','bot','assigned','snoozed','closed')),
  unread_count INT NOT NULL DEFAULT 0,
  last_message_at VARCHAR(255),
  last_message_preview TEXT,
  window_expires_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  bot_flow_id VARCHAR(64),
  bot_node_id TEXT,
  bot_handed_over INT NOT NULL DEFAULT 0,
  UNIQUE (tenant_id, channel, phone),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (contact_id) REFERENCES client_contacts(id) ON DELETE SET NULL,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (bot_flow_id) REFERENCES chatbot_flows(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE chat_messages (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  thread_id VARCHAR(64) NOT NULL,
  direction TEXT NOT NULL CHECK (direction IN ('inbound','outbound')),
  type TEXT NOT NULL
                        CHECK (type IN ('text','image','document','audio','video','template','interactive','location','system')),
  body TEXT,
  media_key TEXT,
  media_mime TEXT,
  media_name TEXT,
  template_id TEXT,
  sent_by VARCHAR(64),
  is_bot INT NOT NULL DEFAULT 0,
  provider_message_id TEXT,
  status TEXT NOT NULL
                        CHECK (status IN ('queued','sent','delivered','read','failed','received')),
  error_message TEXT,
  linked_document_id VARCHAR(64),
  created_at VARCHAR(255) NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (thread_id) REFERENCES chat_threads(id) ON DELETE CASCADE,
  FOREIGN KEY (sent_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (linked_document_id) REFERENCES documents(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
CREATE TABLE broadcast_recipients (
  id VARCHAR(64) PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  broadcast_id VARCHAR(64) NOT NULL,
  client_id VARCHAR(64),
  user_id VARCHAR(64),
  to_address VARCHAR(255) NOT NULL,
  status VARCHAR(255) NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','sent','delivered','failed','skipped')),
  provider_message_id TEXT,
  error TEXT,
  attempts INT NOT NULL DEFAULT 0,
  sent_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (broadcast_id) REFERENCES broadcasts(id) ON DELETE CASCADE,
  FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

